// What the dashboard asks for (dashboard/app/services/writing.py), made into
// a prompt for the shared LLM call. Five kinds: subject lines and preview
// texts to choose from, the greeting, why a trend matters, an editor's
// question to the articles, and a follow-up question written out whole so the
// articles for it can be found. Everything is a suggestion an editor reads
// before it goes anywhere.
// Jira: DM42-25, DM42-37, DM42-40
const body = $json.body || {};
const kind = String(body.task || '');
const attempt = Math.max(1, Math.min(50, Math.floor(Number(body.attempt) || 1)));
const articles = Array.isArray(body.articles) ? body.articles.slice(0, 20) : [];
const clean = (s, n) => String(s || '').replace(/\s+/g, ' ').trim().slice(0, n);

const WHO = 'Olet Suomen eOppimiskeskus ry:n uutiskirjeen toimittaja. Yhdistys edistää digitaalista oppimista, '
  + 'ja uutiskirjeen lukijat ovat sen jäseniä: opettajia, kouluttajia ja oppilaitosten väkeä.';
const PLAIN = '- Vastaa pelkällä tekstillä ilman otsikkoa, lainausmerkkejä tai muotoiluja.';
// A new attempt asks for other words. It also changes what the cache is
// keyed on, so the editor gets something new rather than the same answer.
const AGAIN = attempt > 1
  ? `\n\nTämä on uusi ehdotus (${attempt}.): käytä eri sanoja ja eri näkökulmaa kuin aiemmin.` : '';

// The newsletter's articles by section, as the editors picked them.
function contents() {
  const lines = [];
  let section = null;
  for (const a of articles) {
    if (a.section !== section) {
      section = a.section;
      lines.push('', clean(section, 80));
    }
    const head = [clean(a.title, 200), a.publisher ? `(${clean(a.publisher, 80)})` : '',
      a.event ? `[${clean(a.event, 80)}]` : ''].filter(Boolean).join(' ');
    lines.push(`- ${head}${a.summary ? `: ${clean(a.summary, 400)}` : ''}`);
  }
  return `Uutiskirje: ${clean(body.newsletter, 120)}\n\nSisältö:${lines.join('\n')}`;
}

const PROMPTS = {
  subject: () => ({
    system: `${WHO}\n\nEhdota uutiskirjeelle aiherivejä ja esikatselutekstejä alla olevan sisällön perusteella.\n\n`
      + '- Kirjoita suomeksi.\n'
      + '- Ehdota kolme erilaista aiheriviä. Aiherivi on enintään 60 merkkiä ja kertoo konkreettisesti, mitä kirjeessä on. '
      + 'Ei huutomerkkejä, ei emojeja, ei klikkiotsikoita.\n'
      + '- Ehdota kaksi esikatselutekstiä. Esikatseluteksti on enintään 110 merkkiä ja täydentää aiheriviä toistamatta sitä.\n'
      + '- Käytä vain alla mainittuja asioita. Älä keksi tapahtumia, päivämääriä, lukuja tai nimiä.\n\n'
      + 'Vastaa pelkkänä JSON-oliona: {"aiherivit": ["…", "…", "…"], "esikatselutekstit": ["…", "…"]}',
    text: contents(),
    json: true,
  }),
  greeting: () => ({
    system: `${WHO}\n\nKirjoita uutiskirjeen alkuun muutama rivi lukijoille siitä, mitä tässä kirjeessä on.\n\n`
      + '- Kirjoita suomeksi, lämpimästi mutta asiallisesti, yhdistyksen toimiston äänellä (me).\n'
      + '- Kahdesta neljään virkettä, yksi kappale.\n'
      + '- Nosta esiin kaksi tai kolme kiinnostavinta asiaa alla olevasta sisällöstä.\n'
      + '- Älä keksi mitään, mitä sisällössä ei ole: ei tapahtumia, päivämääriä, lukuja eikä toimiston kuulumisia.\n'
      + '- Älä aloita tervehdyksellä äläkä lopeta allekirjoitukseen: ne ovat kirjeessä jo.\n'
      + PLAIN,
    text: contents(),
    json: false,
  }),
  trend: () => ({
    system: `${WHO}\n\nUutiskirjeessä on laatikko nousevasta aiheesta. Kirjoita siihen, mistä aiheessa on alla olevien `
      + 'juttujen perusteella kyse ja miksi se on lukijoille nyt ajankohtainen.\n\n'
      + '- Kirjoita suomeksi, selkeästi ja asiallisesti.\n'
      + '- Kaksi tai kolme virkettä, yksi kappale.\n'
      + '- Perusta kaikki alla oleviin juttuihin. Älä keksi tutkimuksia, lukuja tai nimiä.\n'
      + '- Älä luettele juttuja, älä toista niiden otsikoita äläkä kerro juttujen määrää: ne ovat laatikossa jo.\n'
      + PLAIN,
    text: `Aihe: ${clean(body.topic, 80)}\n\nJutut:\n\n` + articles.map((a, i) =>
      `${i + 1}. ${clean(a.title, 200)}${a.publisher ? ` (${clean(a.publisher, 80)})` : ''}\n${clean(a.summary, 700)}`).join('\n\n'),
    json: false,
  }),
  // The articles that fit the question best, numbered, so the answer can say
  // which one each thing is from and the dashboard can link it.
  ask: () => ({
    system: `${WHO}\n\nVastaa toimittajan kysymykseen pelkästään alla olevien juttujen perusteella.\n\n`
      + '- Vastaa suomeksi, kolmesta kuuteen virkettä.\n'
      + '- Kerro jokaisen asian perässä, mistä jutusta se on: jutun numero hakasulkeissa, esimerkiksi [2].\n'
      + '- Jos jutut eivät vastaa kysymykseen, sano se suoraan äläkä arvaa.\n'
      + '- Älä keksi mitään, mitä jutuissa ei ole.\n'
      + PLAIN,
    text: `Kysymys: ${clean(body.question, 300)}\n\nJutut:\n\n` + articles.map((a, i) => {
        const about = [clean(a.publisher, 80), clean(a.date, 20)].filter(Boolean).join(', ');
        return `[${i + 1}] ${clean(a.title, 200)}${about ? ` (${about})` : ''}\n${clean(a.summary, 800)}`;
      }).join('\n\n'),
    json: false,
  }),
  // A follow-up in Kysy artikkeleilta ("Entä lukioissa?") written as a whole
  // question, with what it refers to in the conversation, so the articles
  // can be found for it. The answer then comes as for any question.
  standalone: () => ({
    system: `${WHO}\n\nToimittaja jatkaa keskustelua uutisjutuista. Päätä, viittaako uusi kysymys aiempaan keskusteluun.\n\n`
      + '- Jos uusi kysymys on ymmärrettävä yksinään, palauta se täsmälleen sellaisenaan, vaikka sen aihe olisi eri kuin aiemmin.\n'
      + '- Vain jos se ei ole ymmärrettävä yksinään, kuten "Entä lukioissa?", "Kerro lisää" tai "Mitä niistä sanotaan?", kirjoita se kokonaiseksi kysymykseksi aiemman keskustelun perusteella. Jos se viittaa juttuun numerolla tai järjestyksellä, kuten [2] tai "toinen juttu", kirjoita jutun aihe auki.\n'
      + '- Kirjoita yksi kysymys suomeksi, enintään 200 merkkiä. Älä vastaa kysymykseen.\n'
      + PLAIN
      + '\n\nEsimerkkejä, kun aiempi kysymys oli "Mitä on kerrottu oppimistulosten laskusta?":\n'
      + 'Entä lukioissa? → Mitä on kerrottu oppimistulosten laskusta lukioissa?\n'
      + 'Mitä etäopetuksesta on kerrottu? → Mitä etäopetuksesta on kerrottu?',
    text: `Aiempi kysymys: ${clean(body.previous_question, 300)}\n\nAiempi vastaus: ${clean(body.previous_answer, 1500)}\n\n`
      + `Aiemman vastauksen jutut:\n${(Array.isArray(body.previous_titles) ? body.previous_titles.slice(0, 8) : [])
        .map((x, i) => `[${i + 1}] ${clean(x, 200)}`).join('\n')}\n\nUusi kysymys: ${clean(body.question, 300)}`,
    json: false,
  }),
};

// A follow-up needs the conversation rather than articles; the others need articles.
const needsArticles = kind !== 'standalone';
if (!PROMPTS[kind] || (needsArticles && !articles.length)) {
  return [{ json: { invalid: true, kind, message: PROMPTS[kind] ? 'Nothing to write from: no articles.' : `Unknown task "${kind}".` } }];
}
const p = PROMPTS[kind]();
// task is what llm_usage records the call as: writing-subject,
// writing-greeting, writing-trend, writing-ask or writing-standalone.
return [{ json: { kind, task: `writing-${kind}`, item_id: null, system_prompt: p.system + AGAIN, user_text: p.text, json: p.json } }];

// What the dashboard gets back: always an answer, with ok saying whether the
// AI wrote something. A model that is down comes back as ok: false and a
// message, rather than as a failed run that would alert the team for every
// press of the button.
const req = $('Build prompt').first().json;
if (req.invalid) return [{ json: { ok: false, code: 'ai_bad_request', message: req.message } }];
const r = $json || {};
if (r.error || typeof r.text !== 'string') {
  return [{ json: { ok: false, code: 'ai_failed', message: 'The AI did not answer. Try again in a moment.' } }];
}
const usage = {
  tokens: (Number(r.tokens_in) || 0) + (Number(r.tokens_out) || 0) || null,
  cost_eur: r.cost_eur ?? null,
  truncated: r.truncated === true,
};
// Quotes, bold and headings the model adds although it was asked not to.
const tidy = (s) => String(s || '').replace(/\*\*|__/g, '').replace(/^#+\s*/gm, '')
  .replace(/^\s*["“”„«»']+|["“”„«»']+\s*$/g, '').replace(/\n{3,}/g, '\n\n').trim();

if (req.kind === 'subject') {
  let parsed = null;
  try {
    parsed = JSON.parse(r.text);
  } catch (e) {
    const object = r.text.match(/\{[\s\S]*\}/);
    try { parsed = object ? JSON.parse(object[0]) : null; } catch (e2) { parsed = null; }
  }
  const list = (v, n) => (Array.isArray(v) ? v : []).map((x) => tidy(x).replace(/\s+/g, ' ').slice(0, 150))
    .filter((x, i, all) => x && all.indexOf(x) === i).slice(0, n);
  const subjects = parsed ? list(parsed.aiherivit || parsed.subjects, 3) : [];
  const preheaders = parsed ? list(parsed.esikatselutekstit || parsed.preheaders, 2) : [];
  if (!subjects.length) {
    return [{ json: { ok: false, code: 'ai_failed',
      message: usage.truncated ? 'The AI ran out of room before it finished.' : 'The AI gave no subject lines.' } }];
  }
  return [{ json: { ok: true, subjects, preheaders, ...usage } }];
}
const text = tidy(r.text);
if (!text) return [{ json: { ok: false, code: 'ai_failed', message: 'The AI gave back no text.' } }];
return [{ json: { ok: true, text, ...usage } }];
